class Solution {
public:
    string reformatNumber(string number) {
        int cnt = 0;
        for (char c : number) {
            if (c >= '0' && c <= '9') cnt++;
        }
        string res;
        int i = 0;
        for (char c : number) {
            if (c < '0' || c > '9') continue;
            if (i > 0) {
                bool dash = false;
                if (cnt % 3 == 1) {
                    if ((i % 3 == 0 && i < cnt - 2) || i == cnt - 2) dash = true;
                } else {
                    if (i % 3 == 0) dash = true;
                }
                if (dash) res.push_back('-');
            }
            res.push_back(c);
            i++;
        }
        return res;
    }
};
